    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
I=np.array(G['Demo pair 1 input']); O=np.array(G['Demo pair 1 output']); H,W=I.shape
fills=[(r,c,int(O[r,c])) for r in range(H) for c in range(W) if I[r,c]==0 and O[r,c]!=0]
bad=[]
for r,c,v in fills:
    found=[]
    rr=r-1
    while rr>=0 and I[rr,c]==0: rr-=1
    if rr>=0 and I[rr,c]!=0: found.append(('vup',int(I[rr,c]),abs(r-rr)))
    rr=r+1
    while rr<H and I[rr,c]==0: rr+=1
    if rr<H and I[rr,c]!=0: found.append(('vdown',int(I[rr,c]),abs(rr-r)))
    sc=c-1
    while sc>=0 and I[r,sc]==0: sc-=1
    if I[r,sc]!=0: found.append(('left',int(I[r,sc]),abs(c-sc)))
    sc=c+1
    while sc<W and I[r,sc]==0: sc+=1
    if I[r,sc]!=0: found.append(('right',int(I[r,sc]),abs(sc-c)))
    cand={x[1]:x[2] for x in found}
    if len(set(cand.values()))!=1 or next(iter(cand.values()))!=v:
        bad.append((r,c,v,cand))
print('count',len(bad), bad[:10])

