        b0,b1=b_[0],b_[-1]
        for r in range(b0,b1+1):
            for c in range(W):
                if g[r,c]!=0: continue
                # horizontal candidates in this band row
                L=None;R=None
                cc=c-1
                while cc>=0 and g[r,cc]==0: cc-=1
                if cc>=0: L=(c-cc,int(g[r,cc]))
                cc=c+1
                while cc<W and g[r,cc]==0: cc+=1
                if cc<W: R=(cc-c,int(g[r,cc]))
                V=None;U=D=None
                rc=r-1
                while rc>=b0 and g[rc,c]==0: rc-=1
                if rc>=b0: U=(r-rc,int(g[rc,c]))
                rc=r+1
                while rc<=b1 and g[rc,c]==0: rc+=1
                if rc<=b1: D=(rc-r,int(g[rc,c]))
                # choose nearest by distance; ties -> smaller color? or prefer existing horizontal fill?
                cands=[x for x in (L,R,U,D) if x]
                if not cands: continue
                d=min(x[0] for x in cands)
                hits=[int(x[1]) for x in cands if x[0]==d]
                out[r,c]=min(hits)
    return out.tolist()
