    Hh,Ww=len(I),len(I[0]); res=[]
    for r in range(Hh):
        row=[]
        for c in range(Ww):
            if I[r][c]==0:
                cc=Counter()
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        rr,ccol=r+dr,c+dc
                        if 0<=rr<Hh and 0<=ccol<Ww and I[rr][ccol]!=0: cc[I[rr][ccol]]+=1
                row.append((dict(cc), I[r][c]))
            else: row.append(None)
        res.append(row)
    return res
